const emptyCampus=()=>({newsCategories:null,teaching:null,modules:[],announcements:[],documents:[],library:[],complaints:[],news:[],lost:[],spaces:[],resources:[],locations:[],listings:[],categories:[],transactions:[],recommendations:[],unavailable:[]});
Object.assign(state,{staffProgram:'all',staffSemester:'all',recoveryNotice:'',recoveryEmail:'',recoveryStatus:'unknown',workspace:emptyCampus(),workspaceError:'',publicData:null,publicError:'',publicLoading:true,newsId:null,newsDetail:null,newsDetailError:'',newsDetailLoading:false,tabs:{},selectedRole:'student',activeRole:'',contentQuery:'',chat:[],conversations:[],conversationId:null,chatBusy:false,locationId:null});
if(!location.hash)state.page='landing';
const recoveryQuery=new URLSearchParams(location.search);
if(recoveryQuery.get('recovery')==='invalid'){state.recoveryNotice='Ce lien a expiré, a déjà été utilisé ou doit être ouvert dans le navigateur qui l’a demandé. Demandez un nouveau lien.';recoveryQuery.delete('recovery');history.replaceState(null,'',location.pathname+(recoveryQuery.size?'?'+recoveryQuery.toString():'')+location.hash)}
if(new URLSearchParams(location.search).get('auth')==='failed')authNotice='Le lien de connexion est expiré ou invalide. Réessayez.';
Object.assign(pageTitles,{landing:'Accueil',login:'Connexion',register:'Créer un compte','choose-profile':'Choix du profil',announcements:'Annonces',documents:'Documents de cours',library:'Smart Library',complaints:'Réclamations',news:'Actualités',lost:'Lost & Found',collaboration:'Collaboration',assistant:'FPK GPT',recommendations:'Pour vous',map:'FPK Map',marketplace:'Marketplace',teaching:'Espace enseignant','teaching-modules':'Mes enseignements','teaching-schedule':'Emploi du temps enseignant',campus:'Découvrir la FPK','news-detail':'Actualité','forgot-password':'Mot de passe oublié','reset-password':'Nouveau mot de passe'});
const themeToggle=()=>window.CampusTheme?.button()||'';
const brand=()=>`<a class="brand" href="#landing" aria-label="CampusConnect, accueil"><span class="brand-mark">${icon('grad')}</span><span class="brand-name">Campus<span>Connect</span><small>FPK · USMS</small></span></a>`;
const notice=(message,kind='')=>message?`<div class="notice ${kind}" role="${kind==='error'?'alert':'status'}">${esc(message)}</div>`:'';
const badge=(text,color='')=>`<span class="tag ${color}">${esc(text)}</span>`;
const fileLink=(file,label='Télécharger')=>file?`<a class="btn secondary small" href="/api/files/${encodeURIComponent(file)}">${icon('download')}${esc(label)}</a>`:'';
const shortDate=value=>value?new Date(value).toLocaleDateString('fr-MA',{day:'numeric',month:'short',year:'numeric',timeZone:'Africa/Casablanca'}):'';
const matchesQuery=row=>JSON.stringify(row).toLocaleLowerCase('fr').includes(state.contentQuery.toLocaleLowerCase('fr'));
const rowButton=(actionName,id,label='Consulter')=>action(actionName,label+' '+icon('chevron'),'text-btn',`data-id="${esc(id)}"`);
const panelList=(rows,renderRow,label='Aucun élément publié')=>rows.length?`<div class="panel resource-list">${rows.map(renderRow).join('')}</div>`:empty(label,'Les contenus accessibles apparaîtront ici.','book');
const searchBox=placeholder=>`<div class="toolbar"><label class="search-input">${icon('search')}<input id="content-search" value="${esc(state.contentQuery)}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></label></div>`;
const tabs=(group,items,selected)=>`<div class="tabs" role="group" aria-label="Filtrer">${items.map(([value,label])=>action('set-tab',label,'tab '+(selected===value?'active':''),`data-group="${group}" data-value="${esc(value)}" aria-pressed="${selected===value}"`)).join('')}</div>`;
const getTab=(group,fallback)=>state.tabs[group]||fallback;
const roleAllowed=role=>role==='teacher'?(hasRole('teacher')||hasRole('department_head')):hasRole(role);
const basePage=currentPage,baseAction=onAction,baseDepartment=department,baseProfile=profilePage;
let refreshSequence=0,publicRequest=null;
const publicView=()=>['landing','campus','news','news-detail','events','login','register','help'].includes(state.page);
function visitorData(data){
  const programs=data?.programs||[];
  const selected=programs.find(p=>p.id===state.program)||programs[0];
  state.program=selected?.id||'';
  return {user:null,programs,events:data?.events||[],semesters:[],modules:[],schedule:[],program:state.program,semester:'',semesterId:'',academicYear:'',demoEnabled:false};
}
async function loadPublicSite(force=false){
  if(publicRequest)return publicRequest;
  if(state.publicData&&!force)return state.publicData;
  state.publicLoading=true;
  publicRequest=(async()=>{
    try{
      const data=await api('/public');
      if(!Array.isArray(data.programs)||!Array.isArray(data.news)||!Array.isArray(data.events))throw new Error('Les informations publiques sont momentanément indisponibles.');
      state.publicData=data;state.publicError='';
    }catch(error){state.publicError='Les informations publiques sont momentanément indisponibles. Réessayez dans un instant.'}
    finally{
      state.publicLoading=false;publicRequest=null;
      if(!state.user)state.data=visitorData(state.publicData);
      if(publicView())render();
    }
    return state.publicData;
  })();
  return publicRequest;
}
refresh=async function(){
  const sequence=++refreshSequence;
  if(!state.user){
    state.workspace=emptyCampus();state.activeRole='';state.error=null;
    await loadPublicSite(true);
    if(sequence===refreshSequence){state.data=visitorData(state.publicData);render()}
    return;
  }
  try{
    const data=await api('/bootstrap?program='+encodeURIComponent(state.program)+'&semester='+encodeURIComponent(state.semesterId||state.semester));
    if(sequence!==refreshSequence)return;
    Object.assign(state,{data,user:data.user,program:data.program,semester:data.semester,semesterId:data.semesterId,error:null});
    if(data.user){
      state.activeRole=spaceRole();state.selectedRole=state.activeRole;
      try{const workspace=await api('/campus');if(sequence===refreshSequence){state.workspace=workspace;state.workspaceError=''}}catch(error){state.workspace=emptyCampus();state.workspaceError=error.message}
    }else{state.workspace=emptyCampus();state.activeRole=''}
  }catch(error){state.error=error.message}
  await loadPublicSite(true);
  if(sequence===refreshSequence)render();
};

function publicHeader(active='landing'){
  return `<header class="public-header">${brand()}<nav aria-label="Navigation publique"><a href="#landing" ${active==='landing'?'aria-current="page" class="active"':''}>Accueil</a><a href="#campus" ${active==='campus'?'aria-current="page" class="active"':''}>Découvrir la FPK</a><a href="#news" ${active==='news'?'aria-current="page" class="active"':''}>Actualités</a><a href="#events" ${active==='events'?'aria-current="page" class="active"':''}>Événements</a></nav><div class="public-actions">${themeToggle()}${state.user?'<a class="btn" href="#dashboard">Mon espace '+icon('arrow')+'</a>':'<a class="btn secondary small" href="#login">Se connecter</a><a class="btn dark small" href="#register">Créer un compte</a>'}</div></header>`;
}
function publicMobileNav(){return '<nav class="public-mobile-nav" aria-label="Navigation visiteurs"><a href="#landing">Accueil</a><a href="#campus">La FPK</a><a href="#news">Actualités</a><a href="#events">Événements</a></nav>'}
function publicShell(content,active){return `<div class="public-shell"><div class="utility-bar"><span>Faculté Polydisciplinaire de Khouribga · Université Sultan Moulay Slimane</span></div>${publicHeader(active)}${publicMobileNav()}<main class="public-content" id="main-content">${content}</main>${publicFooter()}</div>`}
function publicStatus(){
  if(state.publicLoading)return '<p class="public-status" role="status">Chargement des informations du campus…</p>';
  if(state.publicError)return notice(state.publicError,'error')+action('retry-public','Réessayer','btn secondary');
  return '';
}
function campusIntroSection(){return `<section class="public-section campus-intro"><div><div class="eyebrow">OUVERT À TOUS LES VISITEURS</div><h2>Découvrez la Faculté Polydisciplinaire de Khouribga</h2><p>La FPK fait partie de l’Université Sultan Moulay Slimane. Retrouvez ses départements, ses filières et les nouvelles de la vie du campus, sans avoir besoin de vous connecter.</p><a class="btn secondary" href="#campus">Découvrir la FPK ${icon('arrow')}</a></div><div class="visitor-access"><span class="module-icon">${icon('building')}</span><h3>Un accès public aux informations du campus</h3><p>Les actualités publiées et le catalogue d’événements sont consultables librement. Les services pédagogiques et les espaces personnels sont réservés aux membres authentifiés.</p></div></section>`}
const publicNewsCategories={campus:'Vie du campus',research:'Recherche',clubs:'Clubs',partners:'Partenaires'};
const availableNewsCategories=group=>(group==='public-news'?state.publicData?.newsCategories:state.workspace.newsCategories)===false?{campus:publicNewsCategories.campus}:publicNewsCategories;
function publicNewsCard(row){return `<article class="event-card public-news-card">${row.cover_url?`<img class="news-cover" src="${esc(row.cover_url)}" alt="Illustration de ${esc(row.title)}" loading="lazy">`:`<div class="news-placeholder">${icon('building')}</div>`}<div class="event-body"><div class="public-news-meta">${badge(publicNewsCategories[row.category]||'Actualité')}<time datetime="${esc(row.published_at)}">${shortDate(row.published_at)}</time></div><h3>${esc(row.title)}</h3><p>${esc(row.content.slice(0,160))}${row.content.length>160?'…':''}</p>${rowButton('public-news',row.id,'Lire l’actualité')}</div></article>`}
function newsBriefing(){
  const rows=(state.publicData?.news||[]).slice(0,3);
  const message=state.publicLoading?'Chargement des actualités…':state.publicError||state.publicData?.newsAvailable===false?'Les actualités sont momentanément indisponibles.':'Aucune actualité publiée pour le moment.';
  return `<section class="news-briefing" aria-labelledby="news-brief-title"><h2 id="news-brief-title">${icon('mail')}À la une</h2>${rows.length?`<ul class="news-brief-items">${rows.map(row=>`<li><a class="news-brief-item" href="#news/${encodeURIComponent(row.id)}" title="${esc(row.title)}"><time datetime="${esc(row.published_at)}">${shortDate(row.published_at)}</time><span>${esc(row.title)}</span>${icon('arrow')}</a></li>`).join('')}</ul>`:`<p class="news-brief-message" ${state.publicLoading?'role="status"':''}>${message}</p>`}<a class="news-brief-all" href="#news">Toutes les actualités ${icon('arrow')}</a></section>`;
}
function publicNewsSection(){
  const rows=state.publicData?.news||[];
  return `<section class="public-section public-news-preview"><div class="section-heading"><div><div class="eyebrow">LA VIE À LA FPK</div><h2>Actualités du campus</h2></div><a href="#news" class="text-btn">Toutes les actualités ${icon('arrow')}</a></div>${publicStatus()}${state.publicData?.newsAvailable===false?notice('Les actualités ne sont pas encore disponibles.'):rows.length?`<div class="event-grid">${rows.slice(0,3).map(publicNewsCard).join('')}</div>`:!state.publicLoading&&!state.publicError?empty('Aucune actualité publiée','Les prochaines nouvelles du campus apparaîtront ici.','mail'):''}</section>`;
}
function campusPage(){
  const data=state.publicData;
  return heading('Découvrir la FPK','Informations publiques sur notre faculté.')+`<section class="public-campus-hero"><img src="/assets/fpk-campus.jpg" alt="Façade de la Faculté Polydisciplinaire de Khouribga"><div><div class="eyebrow">KHOURIBGA · MAROC</div><h2>Faculté Polydisciplinaire de Khouribga</h2><p>Un établissement de l’Université Sultan Moulay Slimane. CampusConnect rassemble les informations pédagogiques et les services de la communauté étudiante de la FPK.</p><a href="#news" class="btn">Lire les actualités ${icon('arrow')}</a></div></section>${publicStatus()}${data?`<section class="public-campus-section"><div class="section-heading"><h2>Départements</h2></div><div class="program-grid">${data.departments.map(d=>`<article class="program-card"><span>${esc(d.code)}</span><h3>${esc(d.name)}</h3>${d.description?`<p>${esc(d.description)}</p>`:''}</article>`).join('')||'<p class="subtle">Les départements seront présentés ici.</p>'}</div></section><section class="public-campus-section"><div class="section-heading"><h2>Filières de la faculté</h2></div><div class="program-grid">${data.programs.map(p=>`<article class="program-card"><span>${esc(p.id)}</span><h3>${esc(p.name)}</h3><p>${esc(p.department)}</p>${p.description?`<p>${esc(p.description)}</p>`:''}</article>`).join('')||'<p class="subtle">Les filières seront présentées ici.</p>'}</div></section>`:''}<div class="notice public-access-note">La consultation de ces informations et des actualités est libre. La connexion est nécessaire pour accéder aux documents de cours, aux réclamations et aux services personnels.</div>`;
}
function publicNewsPage(){
  const category=getTab('public-news','all'),rows=(state.publicData?.news||[]).filter(row=>matchesQuery(row)&&(category==='all'||row.category===category));
  return heading('Actualités du campus','',newsFilterButton('public-news'))+publicStatus()+(state.publicData?.newsAvailable===false?notice('Les actualités ne sont pas encore disponibles.'):rows.length?`<div class="event-grid public-news-grid">${rows.map(publicNewsCard).join('')}</div>`:!state.publicLoading&&!state.publicError?empty('Aucune actualité pour cette sélection','Modifiez les filtres ou revenez prochainement.','mail'):'');
}
function newsFilterButton(group){
  const count=Number(getTab(group,'all')!=='all')+Number(!!state.contentQuery.trim());
  return action('filter-news',icon('filter')+' Filtrer'+(count?' ('+count+')':''),'btn secondary',`type="button" data-group="${group}" aria-haspopup="dialog"`);
}
function newsFilterForm(group){
  if(!['news','public-news'].includes(group))return;
  modal(`<div class="modal-content"><h2 id="modal-title">Filtrer les actualités</h2><form id="news-filter-form" data-group="${group}"><label>Catégorie<select name="category">${[['all','Toutes les catégories'],...Object.entries(availableNewsCategories(group))].map(([value,label])=>`<option value="${value}" ${getTab(group,'all')===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Rechercher<input name="query" type="search" value="${esc(state.contentQuery)}" maxlength="120" placeholder="Titre ou mot-clé"></label><div class="detail-footer">${action('reset-news-filters','Réinitialiser','btn secondary',`type="button" data-group="${group}"`)}<button type="submit" class="btn">Appliquer les filtres</button></div></form></div>`);
}
function publicEventsPage(){return publicStatus()+(!state.data?'':notice('Le catalogue est public. Les inscriptions sont réservées aux étudiants authentifiés.')+eventPage())}
async function loadPublicNews(id){
  if(!id)return;
  state.newsDetailLoading=true;
  try{const result=await api('/public/news/'+encodeURIComponent(id));if(state.newsId===id){state.newsDetail=result.news;state.newsDetailError=''}}
  catch(error){if(state.newsId===id){state.newsDetail=null;state.newsDetailError='Cette actualité est indisponible ou n’est plus publiée.'}}
  finally{if(state.newsId===id){state.newsDetailLoading=false;if(state.page==='news-detail')render()}}
}
function publicNewsDetailPage(){
  const row=state.newsDetail;
  return `<a href="#news" class="text-btn public-back-link">${icon('arrow')} Toutes les actualités</a>`+(state.newsDetailLoading?'<p role="status">Chargement de l’actualité…</p>':row?`<article class="public-article"><header><div class="eyebrow">ACTUALITÉS · FPK</div><h1>${esc(row.title)}</h1><div class="public-news-meta">${badge(publicNewsCategories[row.category]||'Actualité')}<time datetime="${esc(row.published_at)}">${shortDate(row.published_at)}</time></div></header>${row.cover_url?`<img class="public-article-cover" src="${esc(row.cover_url)}" alt="Illustration de ${esc(row.title)}">`:''}<div class="public-article-content">${row.content.split(/\n{2,}/).map(paragraph=>`<p>${esc(paragraph).replace(/\n/g,'<br>')}</p>`).join('')}</div></article>`:empty('Actualité indisponible',state.newsDetailError||'Cette actualité est introuvable.','mail',action('retry-public-news','Réessayer','btn secondary')));
}

function landing(){
  const published=(state.publicData?.events||[]).filter(isFuture).slice(0,3);
  const services=[
    ['building','Département, modules et emploi du temps','Consultez le responsable de votre département, les modules et les séances de votre filière.','department','MVP 1'],
    ['ticket','Événements du campus','Découvrez les conférences et ateliers, puis gérez vos inscriptions.','events','MVP 1'],
    ['file','Annonces, documents et réclamations','Retrouvez les communications des enseignants et vos supports de cours ; suivez vos réclamations.','announcements','MVP 2'],
    ['users','Actualités et entraide','Consultez les actualités et les objets perdus ou trouvés de la communauté.','news','MVP 2'],
    ['book','Smart Library et collaboration','Recherchez des ressources et partagez des projets entre filières.','library','MVP 2'],
    ['spark','Assistant et services campus','Accédez à FPK GPT, aux recommandations, au plan du campus et au Marketplace étudiant.','assistant','MVP 3']
  ];
  return `<div class="landing"><div class="utility-bar"><span>Faculté Polydisciplinaire de Khouribga · Université Sultan Moulay Slimane</span></div>${publicHeader('landing')}${publicMobileNav()}<main id="main-content">${newsBriefing()}<section class="landing-hero"><div class="landing-copy"><div class="eyebrow"><span class="gold-line"></span>CAMPUSCONNECT · FPK</div><h1>Le portail étudiant<br><em>de la FPK.</em></h1><p>Votre département, vos modules, votre emploi du temps et les services de la vie étudiante, personnalisés selon votre filière.</p><div class="hero-actions"><a class="btn" href="#${state.user?'dashboard':'login'}">${state.user?'Accéder à mon espace':'Se connecter'} ${icon('arrow')}</a><a class="btn secondary" href="#news">Lire les actualités ${icon('mail')}</a></div></div><div class="landing-visual"><img src="/assets/fpk-campus.jpg" alt="Façade de la Faculté Polydisciplinaire de Khouribga"></div></section><section class="public-events" aria-label="Prochains événements"><div class="strip-label">ÉVÉNEMENTS<br>DU CAMPUS ${icon('arrow')}</div>${published.length?published.map(e=>`<button class="strip-event" data-action="detail" data-id="${esc(e.id)}"><span class="strip-day">${esc(e.date.slice(-2))}<small>${fmtDate(e.date,{month:'long'})}</small></span><span><small>${icon('clock')}${esc(e.time)} — ${esc(e.endTime)}</small><strong>${esc(e.title)}</strong><small>${esc(e.location)}</small></span></button>`).join(''):'<div class="strip-empty">Aucun événement à venir n’est publié pour le moment.</div>'}</section>${campusIntroSection()}${publicNewsSection()}<section class="public-section" id="services-campus"><div class="section-heading"><div><div class="eyebrow">VOTRE VIE À LA FPK</div><h2>Les services de CampusConnect</h2></div></div><div class="service-grid">${services.map(([i,title,text,page])=>`<a class="service-card" href="#${state.user?page:['events','news'].includes(page)?page:'login'}"><span class="module-icon">${icon(i)}</span><h3>${title}</h3><p>${text}</p><span class="text-btn">Consulter ${icon('arrow')}</span></a>`).join('')}</div></section></main>${publicFooter()}</div>`;
}
function publicFooter(){return `<footer class="public-footer">${brand()}<p>Faculté Polydisciplinaire de Khouribga<br>Université Sultan Moulay Slimane</p><div><a href="#help">Aide et confidentialité</a><span>© ${new Date().getFullYear()} CampusConnect</span></div></footer>`}
function authFrame(title,description,content){
  return `<main class="auth-layout${state.page==='register'?' auth-register':''}" id="main-content"><section class="auth-panel" aria-labelledby="auth-title"><div class="auth-brand">${brand()}${themeToggle()}<a class="back-home" href="#landing" aria-label="Retour à l’accueil" title="Retour à l’accueil">${icon('arrow')}<span>Retour à l’accueil</span></a></div><div class="auth-content"><div class="eyebrow">CAMPUSCONNECT · FPK</div><h1 id="auth-title">${title}</h1><p>${description}</p>${content}</div><small class="auth-copyright">© ${new Date().getFullYear()} CampusConnect · FPK</small></section></main>`;
}
let recoveryCheckSequence=0;
async function checkRecoveryLink(){
  const sequence=++recoveryCheckSequence;
  try{
    const result=await api('/auth/recovery');
    if(sequence===recoveryCheckSequence)state.recoveryStatus=result.valid?'valid':'invalid';
  }catch(error){if(sequence===recoveryCheckSequence)state.recoveryStatus='error'}
  if(sequence===recoveryCheckSequence&&state.page==='reset-password')render();
}
function authPage(){
  const mode=state.page,register=mode==='register',programs=state.data?.programs||[];
  if(mode==='forgot-password')return authFrame('Mot de passe oublié ?','Indiquez l’adresse email associée à votre compte.',`<form id="experience-auth" data-mode="forgot-password"><label><span class="auth-field-icon">${icon('mail')}</span>Email universitaire<input name="email" type="email" autocomplete="email" required maxlength="180" value="${esc(state.recoveryEmail)}" placeholder="votre.email@exemple.ma"></label><div id="auth-error">${notice(state.recoveryNotice)}</div><button class="btn full" type="submit">Envoyer le lien ${icon('mail')}</button></form><p class="privacy-note">Ouvrez le dernier lien reçu dans ce même navigateur. Le lien est temporaire.</p><p class="auth-link"><a href="#login">Revenir à la connexion</a></p>`);
  if(mode==='reset-password'){
    if(state.recoveryStatus==='unknown'){state.recoveryStatus='checking';checkRecoveryLink()}
    const status=state.recoveryStatus;
    const content=status==='checking'?'<p role="status" class="recovery-status">Vérification du lien de récupération…</p>':status==='valid'?`<form id="experience-auth" data-mode="reset-password"><label><span class="auth-field-icon">${icon('lock')}</span>Nouveau mot de passe<div class="password-field"><input name="password" type="password" autocomplete="new-password" required minlength="8" maxlength="128" placeholder="De 8 à 128 caractères">${action('show-password',icon('eye'),'password-toggle','aria-label="Afficher ou masquer le mot de passe"')}</div></label><label><span class="auth-field-icon">${icon('lock')}</span>Confirmer le nouveau mot de passe<input name="confirmation" type="password" autocomplete="new-password" required minlength="8" maxlength="128" placeholder="Confirmez le nouveau mot de passe"></label><div id="auth-error"></div><button class="btn full" type="submit">Enregistrer mon mot de passe ${icon('check')}</button></form>`:status==='error'?notice('La vérification est momentanément indisponible. Réessayez dans un instant.','error')+action('retry-recovery','Réessayer','btn secondary full'):notice('Ce lien a expiré ou n’est plus valide. Demandez un nouveau lien.','error')+'<a class="btn full" href="#forgot-password">Demander un nouveau lien</a>';
    return authFrame('Nouveau mot de passe','Choisissez un mot de passe différent pour votre compte.',content+'<p class="auth-link"><a href="#login">Revenir à la connexion</a></p>');
  }
  return authFrame(register?'Créer un compte':'Se connecter',register?'Inscrivez-vous avec votre email et votre filière.':'Accédez aux informations de votre filière.',`<form id="experience-auth" data-mode="${register?'register':'login'}">${register?`<label><span class="auth-field-icon">${icon('user')}</span>Nom et prénom<input name="name" autocomplete="name" required minlength="2" maxlength="100" placeholder="Votre nom complet"></label>`:''}<label><span class="auth-field-icon">${icon('mail')}</span>Email universitaire<input name="email" type="email" autocomplete="email" required maxlength="180" ${register?`pattern="${universityEmailPattern}" title="${universityEmailError}" aria-describedby="registration-email-hint"`:''} placeholder="${register?'prenom.nom@usms.ac.ma':'Adresse email universitaire'}">${register?'<small id="registration-email-hint" class="registration-email-hint">Format : prenom.nom@usms.ac.ma</small>':''}</label><label><span class="auth-field-icon">${icon('lock')}</span>Mot de passe<div class="password-field"><input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="8" maxlength="128" placeholder="Au moins 8 caractères">${action('show-password',icon('eye'),'password-toggle','aria-label="Afficher ou masquer le mot de passe"')}</div></label>${register?`<label><span class="auth-field-icon">${icon('lock')}</span>Confirmer le mot de passe<input name="confirmation" type="password" autocomplete="new-password" required minlength="8" maxlength="128" placeholder="Confirmez votre mot de passe"></label>`:''}${register?`<label><span class="auth-field-icon">${icon('layers')}</span>Filière<select name="program" required><option value="">Sélectionnez votre filière</option>${programs.map(p=>`<option value="${esc(p.id)}" ${p.id===state.program?'selected':''}>${esc(p.id)} · ${esc(p.name)}</option>`).join('')}</select></label>`:''}${register?'':'<div class="forgot-link"><a href="#forgot-password">Mot de passe oublié ?</a></div>'}<div id="auth-error">${notice(authNotice)}</div><button class="btn full" type="submit" ${register&&!programs.length?'disabled':''}>${register?icon('user')+' Créer mon compte':icon('arrow')+' Se connecter'}</button></form>${state.error?notice(state.error,'error'):''}<p class="auth-link">${register?'Vous avez déjà un compte ? <a href="#login">Se connecter</a>':'Vous n’avez pas de compte ? <a href="#register">Créer un compte</a>'}</p>${register?'<p class="privacy-note">Confirmez votre adresse email pour accéder à votre espace. Les autorisations des profils sont gérées par l’établissement.</p>':''}`);
}
function chooseProfile(){return `<div class="profile-choice" id="main-content"><div class="profile-choice-toolbar">${brand()}${themeToggle()}</div><div class="eyebrow">CAMPUSCONNECT · FPK</div><h1>Choisissez votre espace</h1><p>Accédez à l’espace correspondant aux autorisations de votre compte.</p><div class="role-grid">${[['student','user','Étudiant','Consulter ma filière et les services étudiants'],['teacher','users','Enseignant / Chef de département','Retrouver mes informations et publications pédagogiques'],['organizer','ticket','Organisateur','Créer et gérer les événements du campus']].map(([role,i,label,description])=>`<button class="role-card ${state.selectedRole===role?'selected':''}" data-action="select-role" data-value="${role}" aria-pressed="${state.selectedRole===role}" ${roleAllowed(role)?'':'disabled'}>${icon(i)}<strong>${label}</strong><span>${description}</span>${roleAllowed(role)?badge('Accès disponible','green'):badge('Accès réservé')}</button>`).join('')}</div>${action('continue-role','Continuer '+icon('arrow'),'btn',roleAllowed(state.selectedRole)?'':'disabled')}<p class="privacy-note">Les autorisations des profils sont gérées par l’établissement.</p><a href="#dashboard" class="text-btn">Retour à mon espace</a></div>`}
const campusNav=[['dashboard','home','Tableau de bord'],['department','building','Mon département'],['modules','book','Modules'],['schedule','calendar','Emploi du temps'],['announcements','mail','Annonces'],['documents','file','Documents'],['complaints','help','Réclamations'],['events','ticket','Événements']];
const communityNav=[['news','home','Actualités'],['lost','search','Lost & Found'],['library','book','Smart Library'],['collaboration','users','Collaboration'],['map','pin','FPK Map'],['marketplace','briefcase','Marketplace'],['assistant','spark','FPK GPT'],['recommendations','grad','Pour vous']];
render=function(){
  const articleMatch=state.page.match(/^news\/([0-9a-f-]{36})$/i);
  if(articleMatch){const id=articleMatch[1];state.page='news-detail';if(state.newsId!==id){state.newsId=id;state.newsDetail=null;state.newsDetailError='';state.newsDetailLoading=true;loadPublicNews(id)}}
  const allowedPages=new Set(['teaching','teaching-modules','teaching-schedule','landing','login','register','forgot-password','reset-password','choose-profile','dashboard','department','modules','schedule','announcements','documents','library','complaints','events','registrations','organizer','news','lost','collaboration','assistant','recommendations','map','marketplace','profile','help','services-campus','campus','news-detail']);
  if(!allowedPages.has(state.page)){state.page='landing';history.replaceState(null,'','#landing')}
  if(state.page==='services-campus'){state.page='landing';render();document.getElementById('services-campus')?.scrollIntoView?.({behavior:'smooth'});return}
  const page=state.page;
  if(page==='landing'){document.getElementById('app').innerHTML=landing();return}
  if(page==='campus'){document.getElementById('app').innerHTML=publicShell(campusPage(),'campus');return}
  if(page==='news-detail'){document.getElementById('app').innerHTML=publicShell(publicNewsDetailPage(),'news');return}
  if(!state.user&&['news','events','help'].includes(page)){document.getElementById('app').innerHTML=publicShell(page==='news'?publicNewsPage():page==='events'?publicEventsPage():helpPage(),page);return}
  if(['login','register','forgot-password','reset-password'].includes(page)){document.getElementById('app').innerHTML=authPage();return}
  if(page==='choose-profile'&&state.user){document.getElementById('app').innerHTML=chooseProfile();return}
  if(!state.user&&!['events','help'].includes(page)){
    document.getElementById('app').innerHTML=`<div class="public-shell"><header class="public-header">${brand()}<div class="public-actions">${themeToggle()}<a class="btn secondary" href="#landing">Accueil</a></div></header><main id="main-content">${empty('Votre campus vous attend','Connectez-vous pour retrouver votre filière, vos ressources et votre communauté.','grad','<a class="btn" href="#login">Se connecter</a>')}</main>${publicFooter()}</div>`;return;
  }
  if(!state.data){document.getElementById('app').innerHTML=`<div class="public-shell"><header class="public-header">${brand()}${themeToggle()}</header><main id="main-content">${empty('Le campus se prépare',state.error||'Chargement des informations…','building',action('retry','Réessayer'))}</main></div>`;return}
  if(page.startsWith('teaching')&&roleAllowed('teacher'))state.activeRole='teacher';
  else if(page==='organizer'&&roleAllowed('organizer'))state.activeRole='organizer';
  else state.activeRole=spaceRole();
  state.selectedRole=state.activeRole;rememberSpace(state.activeRole);
  const user=state.user,items=spaceMenu(),services=communityNav.filter(([route])=>!items.some(item=>item[0]===route)&&(spaceRole()==='student'||!['marketplace','recommendations'].includes(route)));
  const nav=rows=>rows.map(([name,i,label])=>`<a href="#${name}" class="nav-item ${page===name?'active':''}" ${page===name?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');
  document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar">${brand()}<div class="nav-label">ESPACE ${esc(spaceLabel().toLocaleUpperCase('fr'))}</div><nav class="nav-list" aria-label="Espace académique">${nav(items)}</nav><div class="nav-label">SERVICES CAMPUS</div><nav class="nav-list" aria-label="Services et communauté">${nav(services)}</nav><div class="sidebar-campus"><strong>Faculté Polydisciplinaire</strong><p>Khouribga · FPK · USMS</p></div><div class="sidebar-footer">${icon(user?'logout':'user')}${action(user?'logout':'auth',user?'Se déconnecter':'Se connecter','')}</div></aside><div class="mobile-backdrop" data-action="close-menu"></div><main class="main" id="main-content"><header class="topbar">${action('menu',icon('menu'),'mobile-toggle','aria-label="Ouvrir le menu"')}<div class="crumb">${esc(pageTitles[page]||'CampusConnect')}</div><div class="top-actions">${themeToggle()}<a class="btn secondary space-switch" href="#choose-profile" aria-label="Changer d’espace" title="Changer d’espace">${icon('users')}<span>Changer d’espace</span></a><form id="campus-search" class="top-search">${icon('search')}<input name="query" placeholder="Rechercher dans cet espace…" aria-label="Rechercher"><kbd>↵</kbd></form>${user?`<a class="user-button" href="#profile"><span class="avatar">${esc(initials(user.name))}</span><span><strong>${esc(user.name)}</strong><small>${esc(spaceLabel())}</small></span></a>`:'<a class="btn small" href="#login">Se connecter</a>'}</div></header><div class="content">${state.error?notice(state.error,'error'):''}${state.workspaceError?notice('Certains contenus sont indisponibles. '+state.workspaceError,'error'):''}${currentPage()}<footer class="page-footer"><span>© ${new Date().getFullYear()} CampusConnect · Faculté Polydisciplinaire de Khouribga</span><a href="#help">Aide & confidentialité</a></footer></div></main></div>`;
};
dashboard=function(){
  if(spaceRole()==='teacher')return teachingDashboard();
  if(spaceRole()==='organizer')return organizerWorkspace();
  const data=state.workspace,p=pInfo(),today=new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'Africa/Casablanca'}).format(new Date()),day=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(today);
  const classes=state.data.schedule.filter(s=>s.day===day&&(!s.sessionDate||s.sessionDate===todayKey()));
  return `<section class="dashboard-welcome"><div><div class="eyebrow">VOTRE CAMPUS, VOTRE QUOTIDIEN</div><h1>Bonjour, ${esc(state.user?.name.split(' ')[0]||'bienvenue')} <span aria-hidden="true">☀</span></h1><p>Espace ${esc(roleNames[state.activeRole||state.user?.role]||'étudiant')} — Filière ${esc(state.program)} · ${esc(state.semester)}</p></div><div class="welcome-campus"></div></section><div class="quick-stats">${[['calendar','Mon EDT',classes.length+' séance'+(classes.length>1?'s':'')+' aujourd’hui','schedule'],['mail','Annonces',data.announcements.length+' publication'+(data.announcements.length>1?'s':''),'announcements'],['file','Documents',data.documents.length+' fichier'+(data.documents.length>1?'s':''),'documents'],['ticket','Mes événements',events().filter(e=>e.joined).length+' inscription(s)','registrations']].map(([i,title,value,page])=>`<a class="quick-stat" href="#${page}"><span>${icon(i)}</span><strong>${title}</strong><small>${esc(value)}</small></a>`).join('')}</div><div class="dashboard-grid"><section><div class="section-heading"><h2>Prochains cours</h2><a href="#schedule" class="text-btn">Voir l’EDT ${icon('arrow')}</a></div>${panelList(classes,s=>`<div class="resource-row"><span class="file-symbol">${icon('calendar')}</span><div><small>${esc(s.start)} — ${esc(s.end)} · ${esc(s.type)}</small><h3>${esc(s.title)}</h3><p>${esc(s.room)} · ${esc(s.teacher)}</p></div></div>`,'Aucun cours prévu aujourd’hui')}</section><section><div class="section-heading"><h2>Dernières annonces</h2><a href="#announcements" class="text-btn">Voir tout ${icon('arrow')}</a></div>${panelList(data.announcements.slice(0,3),r=>`<button class="resource-row row-link" data-action="view-announcement" data-id="${esc(r.id)}"><span class="file-symbol">${icon('mail')}</span><div><h3>${esc(r.title)}</h3><small>${shortDate(r.published_at)}</small></div>${icon('chevron')}</button>`,'Aucune annonce publiée')}</section></div><div class="section-heading"><h2>À découvrir sur le campus</h2><a href="#events" class="text-btn">Tous les événements ${icon('arrow')}</a></div><div class="event-grid">${nextEvents().slice(0,3).map(eventCard).join('')||empty('Les prochains rendez-vous arrivent','Les événements publiés pour votre filière apparaîtront ici.','ticket')}</div>`;
};
department=function(){const p=pInfo(),tab=getTab('department','presentation');return heading(esc(p.department),'Votre département, son équipe et ses parcours.')+tabs('department',[['presentation','Présentation'],['team','Équipe'],['programs','Filières'],['contact','Contact']],tab)+(tab==='presentation'?`<section class="department-intro panel"><div class="department-illustration">${icon('building')}<span>FPK · KHOURIBGA</span></div><div><div class="eyebrow">FACULTÉ POLYDISCIPLINAIRE</div><h2>${esc(p.department)}</h2><p>${esc(p.description||'Retrouvez les informations pédagogiques, les modules et les emplois du temps de votre filière.')}</p><div class="department-metrics"><div>${icon('user')}<span>Chef de département<strong>${esc(p.head)}</strong></span></div><div>${icon('grad')}<span>Filières<strong>${state.data.programs.filter(x=>x.departmentId===p.departmentId).length} parcours</strong></span></div><div>${icon('book')}<span>Votre semestre<strong>${state.data.modules.length} modules</strong></span></div></div></div></section>`:tab==='team'?`<section class="panel academic-info"><div class="dept-line"><span class="dept-avatar">${esc(p.initials)}</span><div><h2>${esc(p.head)}</h2><p>Chef de département</p></div></div><p>${esc(p.guidance||'Les informations de permanence sont disponibles dans l’onglet Contact.')}</p></section>`:tab==='programs'?`<div class="program-grid">${state.data.programs.filter(x=>x.departmentId===p.departmentId).map(x=>`<div class="program-card"><span>${esc(x.id)}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><a href="#modules" class="text-btn">Consulter les modules ${icon('arrow')}</a></div>`).join('')}</div>`:`<section class="panel academic-info"><h2>Nous contacter</h2><p>${icon('mail')}${esc(p.email)}</p><p>${icon('pin')}${esc(p.office)}</p><p>${icon('clock')}${esc(p.hours)}</p></section>`)};

function announcementsPage(){const data=state.workspace,rows=data.announcements.filter(matchesQuery);return heading('Annonces des enseignants','Les informations qui accompagnent votre parcours.',spaceRole()==='teacher'?action('new-resource',icon('plus')+' Publier une annonce','btn','data-kind="announcement"'):'')+searchBox('Rechercher une annonce…')+panelList(rows,r=>`<button class="resource-row row-link" data-action="view-announcement" data-id="${esc(r.id)}"><span class="file-symbol">${icon('mail')}</span><div><h3>${esc(r.title)}</h3><p>${esc(data.modules.find(m=>m.id===r.module_id)?.title||'Votre filière')} · ${shortDate(r.published_at)}</p></div>${badge(r.status==='published'?'Publié':'Brouillon')}${icon('chevron')}</button>`)}
function documentsPage(library=false){const data=state.workspace,rows=(library?data.library:data.documents).filter(matchesQuery).filter(r=>getTab('document-type','all')==='all'||(library?r.resource_type:r.document_type)===getTab('document-type','all'));return heading(library?'Smart Library':'Documents de cours',library?'Des connaissances à explorer et à partager.':'Vos supports de cours, TD et TP, au même endroit.',library||spaceRole()==='teacher'?action('new-resource',icon('plus')+(library?' Ajouter une ressource':' Publier un document'),'btn',`data-kind="${library?'library':'document'}"`):'')+`<div class="tabs"><a href="#documents" class="tab ${!library?'active':''}">Documents de cours</a><a href="#library" class="tab ${library?'active':''}">Smart Library</a></div>`+searchBox('Rechercher un document, un livre, un article…')+tabs('document-type',library?[['all','Tous'],['book','Livres'],['article','Articles'],['project_report','Rapports'],['course_support','Supports']]:[['all','Tous'],['course','Cours'],['td','TD'],['tp','TP'],['exam','Examens']],getTab('document-type','all'))+panelList(rows,r=>`<div class="resource-row"><span class="file-symbol ${library?'':'pdf'}">${icon(library?'book':'file')}${library?'':'<small>PDF</small>'}</span><div><h3>${esc(r.title)}</h3><p>${esc(library?r.authors||r.resource_type:data.modules.find(m=>m.id===r.module_id)?.title||r.document_type)} · ${shortDate(r.created_at)}</p></div>${library?rowButton('view-library',r.id):fileLink(r.file_id)}</div>`)}
const complaintLabels={submitted:'Soumise',under_review:'En cours',resolved:'Résolue',rejected:'Rejetée'};
function complaintsPage(){
  const staff=spaceRole()==='teacher',status=getTab('staff-complaints','all');
  const rows=state.workspace.complaints.filter(r=>staff?r.manageable:r.student_id===state.user.id).filter(matchesQuery).filter(r=>!staff||status==='all'||r.status===status);
  return heading(staff?'Réclamations à traiter':'Mes réclamations',staff?'Les dossiers pour lesquels vous êtes responsable.':'Soumettez et suivez vos réclamations pédagogiques et techniques.',!staff&&hasRole('student')?action('new-resource',icon('plus')+' Nouvelle réclamation','btn','data-kind="complaint"'):'')+
    (staff?tabs('staff-complaints',[['all','Toutes'],['submitted','Soumises'],['under_review','En cours'],['resolved','Résolues'],['rejected','Rejetées']],status):'')+searchBox('Rechercher une réclamation…')+panelList(rows,r=>`<button class="resource-row row-link" data-action="view-complaint" data-id="${esc(r.id)}"><span class="file-symbol">${icon('help')}</span><div><h3>${esc(r.subject)}</h3><small>#${esc(r.id.slice(0,8))} · ${shortDate(r.submitted_at)}</small></div>${badge(complaintLabels[r.status],r.status==='resolved'?'green':'')}${icon('chevron')}</button>`,staff?'Aucune réclamation à traiter':'Aucune réclamation');
}
function newsPage(){return heading('Actualités','',`<div class="news-actions">${newsFilterButton('news')}${hasRole('organizer')||hasRole('teacher')||hasRole('department_head')?action('new-resource',icon('plus')+' Publier une actualité','btn','data-kind="news"'):''}</div>`)+`<div class="event-grid">${state.workspace.news.filter(matchesQuery).filter(r=>getTab('news','all')==='all'||(r.category||'campus')===getTab('news','all')).map(r=>`<article class="event-card">${r.cover_file_id?`<img class="news-cover" src="/api/files/${encodeURIComponent(r.cover_file_id)}?inline=1" alt="">`:`<div class="news-placeholder">${icon('building')}</div>`}<div class="event-body"><span class="eyebrow">VIE DU CAMPUS</span><h3>${esc(r.title)}</h3><p>${esc(r.content.slice(0,130))}${r.content.length>130?'…':''}</p><div class="section-heading"><small>${shortDate(r.published_at||r.created_at)}</small>${rowButton('view-news',r.id,'Lire')}</div></div></article>`).join('')||empty('Aucune actualité pour cette sélection','Modifiez les filtres ou revenez prochainement.','mail')}</div>`}
function lostPage(){const tab=getTab('lost','all'),rows=state.workspace.lost.filter(matchesQuery).filter(r=>tab==='all'||tab==='returned'?tab==='all'||r.status==='returned':r.item_type===tab&&r.status==='open');return heading('Lost & Found','Un objet perdu ? La communauté peut vous aider.',action('new-resource',icon('plus')+' Déclarer un objet','btn','data-kind="lost"'))+tabs('lost',[['all','Tous'],['lost','Objets perdus'],['found','Objets trouvés'],['returned','Restitués']],tab)+searchBox('Rechercher un objet ou un lieu…')+panelList(rows,r=>`<button class="resource-row row-link" data-action="view-lost" data-id="${esc(r.id)}">${r.image_file_id?`<img class="item-thumb" src="/api/files/${encodeURIComponent(r.image_file_id)}?inline=1" alt="">`:`<span class="file-symbol">${icon('search')}</span>`}<div><h3>${esc(r.title)}</h3><p>${esc(r.location_text)} · ${shortDate(r.created_at)}</p></div>${badge(r.status==='returned'?'Restitué':r.status==='closed'?'Clôturé':r.item_type==='found'?'Trouvé':'Perdu',r.status==='returned'?'green':'')}${icon('chevron')}</button>`)}
function collaborationPage(){return heading('Collaboration inter-filières','Partagez vos idées et construisez ensemble.',action('new-resource',icon('plus')+' Nouveau projet','btn','data-kind="space"'))+searchBox('Rechercher un projet…')+`<div class="module-grid">${state.workspace.spaces.filter(matchesQuery).map(s=>`<article class="module-card"><div class="module-top"><span class="module-icon">${icon('users')}</span>${badge(s.status==='open'?'Ouvert':'Clôturé',s.status==='open'?'green':'')}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="module-bottom"><span>${s.memberCount} membre(s)</span>${rowButton('view-space',s.id,s.joined?'Ouvrir':'Découvrir')}</div></article>`).join('')||empty('Les projets commencent avec vous','Créez un espace pour rassembler votre équipe.','users')}</div>`}
function assistantPage(){return heading('FPK GPT','Votre assistant pour la vie à la FPK.',action('new-chat',icon('plus')+' Nouvelle conversation','btn secondary'))+`<div class="chat-layout"><aside class="panel chat-history"><h3>Mes conversations</h3>${state.conversations.map(c=>`<button class="history-item ${state.conversationId===c.id?'active':''}" data-action="open-chat" data-id="${esc(c.id)}">${icon('chat')}<span>${esc(c.title||'Conversation')}</span></button>`).join('')||'<p class="subtle">Vos échanges apparaîtront ici.</p>'}${action('load-chats','Actualiser','text-btn')}</aside><section class="panel chat-panel"><div class="chat-messages" aria-live="polite">${state.chat.length?state.chat.map(m=>`<article class="chat-message ${m.sender}"><span class="avatar">${icon(m.sender==='user'?'user':'spark')}</span><div><strong>${m.sender==='user'?'Vous':'FPK GPT'}</strong><p>${esc(m.content).replace(/\n/g,'<br>')}</p>${m.model_name==='source-search'?'<small class="source-mode">Recherche dans les sources du campus</small>':''}${m.sources?.length?`<div class="source-links">${m.sources.map(s=>`<a href="${esc(s.url)}">${icon('file')}${esc(s.title)}</a>`).join('')}</div>`:''}${m.sender==='assistant'?`<div class="feedback-actions">${action('chat-feedback','Pertinent','text-btn',`data-id="${esc(m.id)}" data-value="true"`)}${action('chat-feedback','Non pertinent','text-btn',`data-id="${esc(m.id)}" data-value="false"`)}</div>`:''}</div></article>`).join(''):`<div class="chat-welcome"><span class="module-icon">${icon('spark')}</span><h2>Bonjour ! Je suis FPK GPT.</h2><p>Recherchez une information sur vos modules, les événements et les ressources du campus.</p><div class="suggestions">${['Quels événements sont proposés ?','Où trouver mes documents de cours ?'].map(q=>action('suggestion',q,'btn secondary small',`data-value="${esc(q)}"`)).join('')}</div></div>`}${state.chatBusy?'<p class="subtle" role="status">Recherche d’une réponse…</p>':''}</div><form id="chat-form" class="chat-input"><label class="sr-only" for="chat-question">Votre question</label><input name="question" id="chat-question" placeholder="Posez votre question…" required minlength="3" maxlength="1500" ${state.chatBusy?'disabled':''}><button class="btn" type="submit" ${state.chatBusy?'disabled':''}>Envoyer ${icon('arrow')}</button></form></section></div>`}
function recommendationsPage(){const data=state.workspace,rows=[...new Map(data.recommendations.map(r=>[r.target_type+':'+r.target_id,r])).values()].slice(0,6);return heading('Pour vous','Des ressources et des rencontres à découvrir.',action('generate-recommendations',icon('spark')+' Actualiser mes suggestions'))+`<div class="module-grid">${rows.map(r=>{const target=r.target_type==='library_resource'?data.library.find(x=>x.id===r.target_id):r.target_type==='shared_resource'?data.resources.find(x=>x.id===r.target_id):state.data.events.find(x=>x.id===r.target_id);if(!target)return'';return `<article class="module-card"><span class="module-icon">${icon(r.target_type==='event'?'ticket':'book')}</span><h3>${esc(target.title)}</h3><p>${esc(r.explanation)}</p>${action(r.target_type==='event'?'detail':r.target_type==='library_resource'?'view-library':'shared-file','Consulter '+icon('arrow'),'btn secondary',`data-id="${esc(target.id)}"`)}<div class="feedback-actions">${action('recommendation-feedback','Pertinent','text-btn',`data-id="${esc(r.id)}" data-value="true"`)}${action('recommendation-feedback','Non pertinent','text-btn',`data-id="${esc(r.id)}" data-value="false"`)}</div></article>`}).join('')||empty('Vos prochaines découvertes','Actualisez les suggestions pour explorer les contenus accessibles de votre campus.','spark')}</div>`}
function mapPage(){const locations=state.workspace.locations.filter(matchesQuery),selected=locations.find(l=>l.id===state.locationId)||locations[0];return heading('FPK Map','Repérez les salles, amphithéâtres et services du campus.','')+searchBox('Rechercher une salle, un bâtiment, un service…')+`<div class="map-layout"><section class="campus-map" aria-label="Plan schématique du campus"><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-garden garden-one"></div><div class="map-garden garden-two"></div><div class="map-caption">FPK · KHOURIBGA<br><small>Plan schématique · positions renseignées par l’équipe</small></div>${locations.filter(l=>l.map_x!=null&&l.map_y!=null&&Number.isFinite(Number(l.map_x))&&Number.isFinite(Number(l.map_y))).map(l=>`<button class="map-marker ${selected?.id===l.id?'selected':''}" style="left:clamp(80px,${Math.max(3,Math.min(90,Number(l.map_x)))}%,calc(100% - 80px));top:${Math.max(7,Math.min(85,Number(l.map_y)))}%" data-action="select-location" data-id="${esc(l.id)}">${icon('pin')}<span>${esc(l.name)}</span></button>`).join('')}${!locations.length?'<div class="map-empty">Les lieux du campus seront affichés ici après leur ajout.</div>':''}</section><aside class="panel map-details">${selected?`<span class="module-icon">${icon('pin')}</span><h2>${esc(selected.name)}</h2><p>${esc(selected.description||'Informations détaillées à venir.')}</p><p>${esc([selected.building,selected.floor_label].filter(Boolean).join(' · '))}</p><span class="tag">${esc({classroom:'Salle',amphitheatre:'Amphithéâtre',lab:'Laboratoire',department:'Département',library:'Bibliothèque',service:'Service',other:'Autre lieu'}[selected.location_type]||selected.location_type)}</span>`:'<h3>Les lieux de votre campus</h3>'}<div class="location-list">${locations.map(l=>action('select-location',esc(l.name)+' '+icon('chevron'),'location-item',`data-id="${esc(l.id)}"`)).join('')}</div></aside></div>`}
const listingTypes={sale:'Cession',loan:'Prêt',donation:'Don',exchange:'Échange'},transactionLabels={requested:'Demandée',accepted:'Acceptée',rejected:'Refusée',completed:'Terminée',cancelled:'Annulée'};
function marketplacePage(){const tab=getTab('marketplace','all'),rows=state.workspace.listings.filter(matchesQuery).filter(r=>tab==='mine'?r.seller_id===state.user.id:tab==='all'?true:r.listing_type===tab);return heading('Marketplace étudiant','Achetez, prêtez, donnez ou échangez entre étudiants.',hasRole('student')?action('new-resource',icon('plus')+' Publier une offre','btn','data-kind="listing"'):'')+tabs('marketplace',[['all','Toutes les offres'],['sale','Cessions'],['loan','Prêts'],['donation','Dons'],['exchange','Échanges'],['mine','Mes offres'],['requests','Mes demandes']],tab)+searchBox('Rechercher du matériel, un livre…')+(tab==='requests'?panelList(state.workspace.transactions,r=>`<div class="resource-row"><span class="file-symbol">${icon('briefcase')}</span><div><h3>${esc(state.workspace.listings.find(l=>l.id===r.listing_id)?.title||'Offre')}</h3><p>${r.owner_id===state.user.id?'Demande reçue':'Ma demande'} · ${shortDate(r.requested_at)}</p></div>${badge(transactionLabels[r.status],r.status==='accepted'?'green':'')}<div class="row-actions">${r.status==='requested'&&r.owner_id===state.user.id?action('decide-transaction','Accepter','btn small',`data-id="${esc(r.id)}" data-value="accepted"`)+action('decide-transaction','Refuser','btn secondary small',`data-id="${esc(r.id)}" data-value="rejected"`):r.status==='accepted'&&r.owner_id===state.user.id?action('decide-transaction','Terminer','btn small',`data-id="${esc(r.id)}" data-value="completed"`):''}${['requested','accepted'].includes(r.status)&&r.requester_id===state.user.id?action('decide-transaction','Annuler','text-btn',`data-id="${esc(r.id)}" data-value="cancelled"`):''}</div></div>`,'Aucune demande en cours'):`<div class="module-grid">${rows.map(r=>`<article class="module-card listing-card">${r.image_file_id?`<img class="listing-card-image" src="/api/files/${encodeURIComponent(r.image_file_id)}?inline=1" alt="${esc(r.title)}">`:`<div class="listing-placeholder">${icon('briefcase')}<span>${esc(listingTypes[r.listing_type])}</span></div>`}<div class="module-top">${badge(r.status==='available'?'Disponible':r.status==='reserved'?'Réservée':'Clôturée',r.status==='available'?'green':'')}</div><h3>${esc(r.title)}</h3><p>${esc(r.description?.slice(0,100))}</p><div class="module-bottom"><strong class="listing-price">${r.listing_type==='sale'?Number(r.price).toLocaleString('fr-MA')+' MAD':esc(listingTypes[r.listing_type])}</strong>${rowButton('view-listing',r.id)}</div></article>`).join('')||empty('Aucune offre pour cette sélection','Partagez du matériel ou un livre avec la communauté.','briefcase')}</div>`)}
profilePage=baseProfile;
helpPage=function(){return heading('Aide & confidentialité','Quelques repères pour utiliser votre campus connecté.')+[['Mon compte','Créez votre compte, confirmez votre adresse email et connectez-vous avec votre email et votre mot de passe. '],['Mes accès','Le profil étudiant donne accès aux services du campus. Les espaces enseignants et organisateurs suivent les rôles attribués par l’établissement.'],['Mes données','Vos réclamations et conversations sont privées. Les documents et ressources sont accessibles selon votre filière et les permissions de leur auteur. Ne publiez que les coordonnées que vous souhaitez partager dans une annonce.'],['Événements et échanges','Les inscriptions sont gratuites. Les demandes Marketplace organisent les échanges entre étudiants ; aucun paiement ni livraison n’est proposé sur le site.']].map(([title,text])=>`<section class="help-card panel"><h2>${title}</h2><p>${text}</p></section>`).join('')};
currentPage=function(){return ({teaching:teachingDashboard,'teaching-modules':teachingModules,'teaching-schedule':teachingSchedule,organizer:organizerWorkspace,announcements:announcementsPage,documents:()=>documentsPage(false),library:()=>documentsPage(true),complaints:complaintsPage,news:newsPage,lost:lostPage,collaboration:collaborationPage,assistant:assistantPage,recommendations:recommendationsPage,map:mapPage,marketplace:marketplacePage}[state.page]||basePage)()};

const inputField=(name,label,type='text',required=true,extra='')=>`<label>${label}<input name="${name}" type="${type}" ${required?'required':''} ${extra}></label>`;
const textField=(name,label,min=10)=>`<label class="span2">${label}<textarea name="${name}" required minlength="${min}" maxlength="6000"></textarea></label>`;
const selectField=(name,label,options,required=true,selected='')=>`<label>${label}<select name="${name}" ${required?'required':''}>${options.map(([value,text])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const attachment=(label='Fichier PDF ou image',required=false,images=false)=>`<label class="span2">${label}<input name="attachment" type="file" accept="${images?'image/png,image/jpeg,image/webp':'application/pdf,image/png,image/jpeg,image/webp'}" ${required?'required':''}><small>10 Mo maximum.</small></label>`;
function resourceSpec(kind,parent=''){
  const modules=state.workspace.modules.filter(m=>kind==='complaint'||m.writable).map(m=>[m.id,m.title]),moduleSelect=selectField('module_id','Module',kind==='complaint'?[['','Sans module'],...modules]:modules,kind!=='complaint',parent);
  return {
    announcement:{title:'Publier une annonce',path:'/announcements',fields:moduleSelect+inputField('title','Titre')+textField('body','Message')},
    document:{title:'Publier un document',path:'/documents',fileKey:'file_id',fields:moduleSelect+inputField('title','Titre')+selectField('document_type','Type',[['course','Cours'],['td','TD'],['tp','TP'],['exam','Examen'],['handout','Polycopié'],['other','Autre']])+textField('description','Description',0)+attachment('Document de cours',true)},
    library:{title:'Partager une ressource',path:'/library',fileKey:'file_id',fields:inputField('title','Titre')+inputField('authors','Auteur(s)','text',false)+selectField('resource_type','Type',[['book','Livre'],['article','Article'],['project_report','Rapport'],['course_support','Support de cours'],['website','Site web'],['other','Autre']])+selectField('visibility','Visibilité',[['all_students','Toutes les filières'],['selected_programs','Ma filière'],['private','Moi uniquement']])+inputField('external_url','Lien externe','url',false)+textField('abstract','Présentation')+attachment()},
    complaint:{title:'Nouvelle réclamation',path:'/complaints',fields:moduleSelect+selectField('complaint_type','Catégorie',[['pedagogical','Pédagogique'],['technical','Technique']])+inputField('subject','Objet')+textField('description','Description')},
    news:{title:'Publier une actualité',path:'/news',fileKey:'cover_file_id',fields:'<div class="notice span2">Cette actualité et sa photo seront visibles par tous les visiteurs, sans compte.</div>'+ inputField('title','Titre')+(state.workspace.newsCategories===false?'<div class="span2"><span class="tag">Catégorie : Vie du campus</span><input type="hidden" name="category" value="campus"></div>':selectField('category','Catégorie',[['campus','Vie étudiante'],['research','Recherche'],['clubs','Clubs'],['partners','Partenaires']]))+textField('content','Contenu',20)+attachment('Photo de couverture',false,true)},
    lost:{title:'Déclarer un objet',path:'/lost-found',fileKey:'image_file_id',fields:inputField('title','Objet')+selectField('item_type','Déclaration',[['lost','Objet perdu'],['found','Objet trouvé']])+inputField('location_text','Lieu')+inputField('item_date','Date','date',false)+inputField('contact_info','Contact à partager')+textField('description','Description')+attachment('Photo de l’objet',false,true)},
    space:{title:'Créer un projet',path:'/collaboration',fields:inputField('title','Nom du projet')+inputField('topic','Thématique','text',false)+textField('description','Présentation')},
    share:{title:'Partager avec le projet',path:'/collaboration/'+encodeURIComponent(parent)+'/resources',fileKey:'file_id',fields:inputField('title','Titre')+selectField('library_resource_id','Ressource de bibliothèque',[['','Choisir un fichier ci-dessous'],...state.workspace.library.filter(r=>r.visibility==='all_students').map(r=>[r.id,r.title])],false)+textField('description','Description')+attachment()},
    listing:{title:'Publier une offre',path:'/marketplace',fileKey:'image_file_id',fields:inputField('title','Titre')+selectField('listing_type','Type d’offre',Object.entries(listingTypes))+selectField('item_condition','État',[['new','Neuf'],['very_good','Très bon état'],['good','Bon état'],['acceptable','État correct'],['not_applicable','Non applicable']])+selectField('category_id','Catégorie',[['','Autre'],...state.workspace.categories.map(c=>[c.id,c.name])],false)+inputField('price','Prix en MAD (cession uniquement)','number',false,'min="0" max="100000" step="0.01"')+textField('description','Description')+attachment('Photo de l’objet',false,true)},
  }[kind];
}
function resourceForm(kind,parent=''){
  if(['announcement','document'].includes(kind)){
    if(!roleAllowed('teacher')){toast('Cet espace est réservé aux enseignants autorisés.');return}
    if(!state.workspace.modules.some(m=>m.writable)){modal(`<div class="modal-content"><h2 id="modal-title">Aucun module de publication</h2><p class="description">Contactez votre département pour faire configurer vos affectations avant de publier une annonce ou un document.</p></div>`);return}
  }
  const spec=resourceSpec(kind,parent);if(!spec)return;
  modal(`<div class="modal-content"><div class="eyebrow">CAMPUSCONNECT · MON ESPACE</div><h2 id="modal-title">${spec.title}</h2><form id="resource-form" data-kind="${kind}" data-parent="${esc(parent)}"><div class="form-grid">${spec.fields}</div><div id="resource-error"></div><div class="detail-footer">${action('close-modal','Annuler','btn secondary')}<button class="btn" type="submit">Enregistrer ${icon('arrow')}</button></div></form></div>`,true);
}
async function openComplaint(id){const {complaint:r,messages}=await api('/complaints/'+encodeURIComponent(id));modal(`<div class="modal-content"><span class="eyebrow">RÉCLAMATION #${esc(r.id.slice(0,8))}</span><h2 id="modal-title">${esc(r.subject)}</h2>${badge(complaintLabels[r.status],r.status==='resolved'?'green':'')}<p class="description">${esc(r.description)}</p><div class="status-track">${['submitted','under_review','resolved'].map(s=>`<span class="${s===r.status?'active':''}">${complaintLabels[s]}</span>`).join('')}</div>${r.resolution_note?notice(r.resolution_note):''}<div class="reply-list">${messages.map(m=>`<div class="reply"><strong>${m.author_id===state.user.id?'Vous':m.author_id===r.student_id?'Étudiant':'Équipe pédagogique'}</strong><p>${esc(m.message)}</p><small>${shortDate(m.created_at)}</small></div>`).join('')}</div><form id="complaint-reply" data-id="${esc(r.id)}"><label>Ajouter un message<textarea name="message" required maxlength="4000"></textarea></label><div id="reply-error"></div><button class="btn" type="submit">Envoyer</button></form>${r.manageable?`<form id="complaint-status" data-id="${esc(r.id)}">${selectField('status','Traiter la réclamation',r.status==='submitted'?[['under_review','Prendre en charge'],['rejected','Rejeter']]:r.status==='under_review'?[['resolved','Résoudre'],['rejected','Rejeter']]:[])}${textField('resolution_note','Réponse',3)}<div id="status-error"></div><button class="btn secondary" type="submit" ${['resolved','rejected'].includes(r.status)?'disabled':''}>Mettre à jour le statut</button></form>`:''}</div>`,true)}
async function openSpace(id){const {space,resources,discussions}=await api('/collaboration/'+encodeURIComponent(id)),summary=state.workspace.spaces.find(s=>s.id===id),joined=summary?.joined||hasRole('admin');modal(`<div class="modal-content"><div class="eyebrow">COLLABORATION INTER-FILIÈRES</div><h2 id="modal-title">${esc(space.title)}</h2><p class="description">${esc(space.description)}</p>${!joined&&space.status==='open'?action('join-space','Rejoindre le projet','btn',`data-id="${esc(id)}"`):badge(space.status==='open'?'Membre du projet':'Projet clôturé','green')}<div class="section-heading"><h3>Ressources</h3>${joined&&space.status==='open'?action('new-resource','Partager','text-btn',`data-kind="share" data-parent="${esc(id)}"`):''}</div>${resources.map(r=>`<div class="resource-row"><div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></div>${r.file_id?fileLink(r.file_id):rowButton('view-library',r.library_resource_id)}</div>`).join('')||'<p class="subtle">Aucune ressource partagée pour le moment.</p>'}<h3>Discussions</h3><div class="reply-list">${discussions.map(d=>`<div class="reply"><strong>${d.author_id===state.user.id?'Vous':'Membre du projet'}</strong><p>${esc(d.message)}</p><small>${shortDate(d.created_at)}</small></div>`).join('')||'<p class="subtle">Lancez la discussion.</p>'}</div>${joined&&space.status==='open'?`<form id="space-message" data-id="${esc(id)}"><label>Votre message<textarea name="message" required maxlength="4000"></textarea></label><div id="space-error"></div><button class="btn" type="submit">Envoyer</button></form>`:''}${space.created_by===state.user.id&&space.status==='open'?action('close-space','Clôturer le projet','text-btn',`data-id="${esc(id)}"`):''}</div>`,true)}
async function loadChats(){try{const data=await api('/assistant');state.conversations=data.conversations;render()}catch(error){toast(error.message)}}
async function openListing(id){const r=state.workspace.listings.find(x=>x.id===id);if(!r)return;const {images}=await api('/marketplace/'+encodeURIComponent(id)+'/images');modal(`<div class="modal-content">${images.length?`<div class="listing-gallery">${images.map(img=>`<img src="/api/files/${encodeURIComponent(img.file_id)}?inline=1" alt="${esc(r.title)}">`).join('')}</div>`:''}<span class="eyebrow">MARKETPLACE ÉTUDIANT</span><h2 id="modal-title">${esc(r.title)}</h2>${badge(listingTypes[r.listing_type])}<strong class="listing-price">${r.listing_type==='sale'?Number(r.price).toLocaleString('fr-MA')+' MAD':''}</strong><p class="description">${esc(r.description)}</p><p>État : ${esc({new:'Neuf',very_good:'Très bon état',good:'Bon état',acceptable:'État correct',not_applicable:'Non applicable'}[r.item_condition])}</p><div class="detail-footer">${r.seller_id===state.user.id?['available','reserved'].includes(r.status)?action('close-listing','Clôturer mon offre','btn secondary',`data-id="${esc(id)}"`):badge('Offre clôturée'):r.status==='available'&&hasRole('student')?action('request-listing','Envoyer une demande','btn',`data-id="${esc(id)}"`):badge(r.status==='reserved'?'Offre réservée':'Offre clôturée')}</div><p class="form-note">Convenez des modalités d’échange entre vous. Aucun paiement en ligne n’est proposé.</p></div>`,true)}

authModal=function(){state.page=state.authMode==='register'?'register':'login';location.hash=state.page;closeModal();render()};
onAction=async function(name,target){const id=target.dataset.id,value=target.dataset.value;
  switch(name){
    case'toggle-theme':window.CampusTheme?.toggle();return;
    case'refresh-participants':if(participantRefresh)await participantRefresh();else await liveParticipants(id);return;
    case'filter-news':newsFilterForm(target.dataset.group);return;
    case'reset-news-filters':if(['news','public-news'].includes(target.dataset.group)){state.tabs[target.dataset.group]='all';state.contentQuery='';closeModal();render()}return;
    case'public-news':location.hash='news/'+id;return;
    case'retry-public':await loadPublicSite(true);return;
    case'retry-public-news':await loadPublicNews(state.newsId);return;
    case'retry-recovery':state.recoveryStatus='unknown';render();return;
    case'auth':state.page='login';location.hash='login';render();return;
    case'auth-register':state.page='register';location.hash='register';render();return;
    case'show-password':{const input=target.closest('.password-field').querySelector('input');input.type=input.type==='password'?'text':'password';target.innerHTML=icon('eye');target.setAttribute('aria-label',input.type==='password'?'Afficher le mot de passe':'Masquer le mot de passe');target.setAttribute('aria-pressed',String(input.type==='text'));return}
    case'select-role':if(!roleAllowed(value)){toast('Ce profil n’est pas attribué à votre compte.');return}state.selectedRole=value;render();return;
    case'continue-role':if(roleAllowed(state.selectedRole)){state.activeRole=state.selectedRole;rememberSpace(state.activeRole);state.page=spaceHome(state.selectedRole);location.hash=state.page;render()}else toast('Ce profil n’est pas attribué à votre compte.');return;
    case'set-tab':state.tabs[target.dataset.group]=value;state.contentQuery='';render();return;
    case'new-resource':resourceForm(target.dataset.kind,target.dataset.parent||'');return;
    case'view-announcement':{const r=state.workspace.announcements.find(x=>x.id===id);if(r)modal(`<div class="modal-content"><div class="eyebrow">ANNONCE ENSEIGNANT</div><h2 id="modal-title">${esc(r.title)}</h2><p class="description pre-line">${esc(r.body)}</p><small>${shortDate(r.published_at)}</small></div>`);return}
    case'view-news':{const r=state.workspace.news.find(x=>x.id===id);if(r)modal(`<div class="modal-content"><div class="eyebrow">VIE DU CAMPUS</div><h2 id="modal-title">${esc(r.title)}</h2><p class="description pre-line">${esc(r.content)}</p><small>${shortDate(r.published_at)}</small></div>`,true);return}
    case'view-library':{const r=state.workspace.library.find(x=>x.id===id);if(!r)return;await api('/library/'+encodeURIComponent(id)+'/view',{method:'POST',body:'{}'});modal(`<div class="modal-content"><div class="eyebrow">SMART LIBRARY</div><h2 id="modal-title">${esc(r.title)}</h2><p>${esc(r.authors)}</p><p class="description pre-line">${esc(r.abstract)}</p><div class="detail-footer">${fileLink(r.file_id)}${r.external_url&&/^https?:\/\//i.test(r.external_url)?`<a class="btn" href="${esc(r.external_url)}" target="_blank" rel="noopener noreferrer">Consulter la ressource ${icon('external')}</a>`:''}</div></div>`,true);return}
    case'view-complaint':await openComplaint(id);return;
    case'view-lost':{const r=state.workspace.lost.find(x=>x.id===id);if(r)modal(`<div class="modal-content"><h2 id="modal-title">${esc(r.title)}</h2>${r.image_file_id?`<img class="lost-detail-image" src="/api/files/${encodeURIComponent(r.image_file_id)}?inline=1" alt="${esc(r.title)}">`:''}<p class="description">${esc(r.description)}</p><p>${icon('pin')}${esc(r.location_text)}</p><div class="notice">Contact de l’auteur : ${esc(r.contact_info||'Non renseigné')}</div>${r.owner_id===state.user.id&&['open','claimed'].includes(r.status)?`<div class="detail-footer">${action('close-lost','Marquer comme restitué','btn',`data-id="${esc(id)}" data-value="returned"`)}${action('close-lost','Clôturer','btn secondary',`data-id="${esc(id)}" data-value="closed"`)}</div>`:''}</div>`);return}
    case'close-lost':await api('/lost-found/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:value})});closeModal();await refresh();toast('Annonce mise à jour.');return;
    case'view-space':await openSpace(id);return;
    case'join-space':await api('/collaboration/'+encodeURIComponent(id)+'/join',{method:'POST',body:'{}'});await refresh();await openSpace(id);return;
    case'close-space':modal(`<div class="modal-content"><h2 id="modal-title">Clôturer ce projet ?</h2><p class="description">Les discussions et ressources seront conservées. Les nouvelles contributions seront fermées.</p><div class="detail-footer">${action('close-modal','Conserver','btn secondary')}${action('confirm-close-space','Clôturer','btn',`data-id="${esc(id)}"`)}</div></div>`);return;
    case'confirm-close-space':await api('/collaboration/'+encodeURIComponent(id),{method:'PATCH',body:'{}'});closeModal();await refresh();return;
    case'select-location':state.locationId=id;render();return;
    case'view-listing':await openListing(id);return;
    case'request-listing':await api('/marketplace/'+encodeURIComponent(id)+'/request',{method:'POST',body:'{}'});closeModal();await refresh();toast('Votre demande a été envoyée. Suivez-la dans Mes demandes.');return;
    case'close-listing':modal(`<div class="modal-content"><h2 id="modal-title">Clôturer cette offre ?</h2><p class="description">Elle ne pourra plus recevoir de demandes. L’historique des échanges sera conservé.</p><div class="detail-footer">${action('close-modal','Conserver','btn secondary')}${action('confirm-close-listing','Clôturer','btn',`data-id="${esc(id)}"`)}</div></div>`);return;
    case'confirm-close-listing':await api('/marketplace/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:'withdrawn'})});closeModal();await refresh();return;
    case'decide-transaction':await api('/marketplace/transactions/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:value})});await refresh();toast('Demande mise à jour.');return;
    case'new-chat':state.chat=[];state.conversationId=null;render();return;
    case'load-chats':await loadChats();return;
    case'open-chat':{const result=await api('/assistant/'+encodeURIComponent(id));state.chat=result.messages;state.conversationId=id;render();return}
    case'suggestion':{const input=document.getElementById('chat-question');input.value=value;input.focus();return}
    case'chat-feedback':await api('/assistant/'+encodeURIComponent(id)+'/feedback',{method:'POST',body:JSON.stringify({is_relevant:value==='true'})});toast('Merci pour votre retour.');return;
    case'generate-recommendations':target.disabled=true;try{await api('/recommendations',{method:'POST',body:'{}'});await refresh()}finally{target.disabled=false}return;
    case'recommendation-feedback':await api('/recommendations/'+encodeURIComponent(id)+'/feedback',{method:'POST',body:JSON.stringify({is_relevant:value==='true'})});toast('Merci pour votre retour.');return;
    case'shared-file':{const r=state.workspace.resources.find(x=>x.id===id);if(r?.file_id)location.href='/api/files/'+encodeURIComponent(r.file_id);else if(r?.library_resource_id)await onAction('view-library',{dataset:{id:r.library_resource_id}});return}
    case'logout':await api('/auth/logout',{method:'POST',body:'{}'});state.user=null;state.data=null;state.workspace=emptyCampus();state.chat=[];state.conversationId=null;state.conversations=[];state.activeRole='';closeModal();location.hash='landing';render();await refresh();return;
    default:return baseAction(name,target);
  }
};

document.addEventListener('submit',async event=>{
  const form=event.target;if(!['experience-auth','news-filter-form','resource-form','complaint-reply','complaint-status','space-message','chat-form','campus-search'].includes(form.id))return;
  event.preventDefault();event.stopImmediatePropagation();const input=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"]'),errorNode=form.querySelector('[id$="error"]');if(submit)submit.disabled=true;if(errorNode)errorNode.innerHTML='';
  try{
    if(form.id==='news-filter-form'){
      const group=form.dataset.group;
      if(!['news','public-news'].includes(group))return;
      state.tabs[group]=Object.hasOwn(availableNewsCategories(group),input.category)?input.category:'all';state.contentQuery=String(input.query||'').trim().slice(0,120);closeModal();render();return;
    }
    if(form.id==='experience-auth'){
      const mode=form.dataset.mode;if(['register','reset-password'].includes(mode)&&input.password!==input.confirmation)throw new Error('Les mots de passe ne correspondent pas.');
      if(mode==='forgot-password'){
        const result=await api('/auth/recover',{method:'POST',body:JSON.stringify({email:input.email})});state.recoveryEmail=input.email;state.recoveryNotice=result.message;render();return;
      }
      if(mode==='reset-password'){
        if(state.recoveryStatus!=='valid')throw new Error('Ouvrez un lien de récupération valide.');
        const result=await api('/auth/password',{method:'POST',body:JSON.stringify({password:input.password,confirmation:input.confirmation})});
        state.user=null;state.workspace=emptyCampus();state.workspaceError='';state.activeRole='';state.chat=[];state.conversations=[];state.conversationId=null;state.recoveryStatus='unknown';state.recoveryEmail='';state.recoveryNotice='';state.error=null;state.data=visitorData(state.publicData);authNotice=result.message;state.page='login';location.hash='login';render();return;
      }
      if(mode==='register'&&!isUniversityEmail(input.email))throw new Error(universityEmailError);
      const credentials={email:input.email?.trim().toLowerCase(),password:input.password};
      if(mode==='register'){credentials.name=input.name;credentials.program=input.program}
      const result=await api(mode==='register'?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(credentials)});
      if(result.requiresEmailConfirmation){authNotice=result.message;state.page='login';location.hash='login';render();return}
      authNotice='';state.workspace=emptyCampus();state.staffProgram='all';state.staffSemester='all';state.user=result.user;state.program=result.user.program;state.semester=result.user.semester;state.semesterId='';state.activeRole='';state.selectedRole=result.user.role;state.page='choose-profile';location.hash='choose-profile';await refresh();return;
    }
    if(form.id==='resource-form'){
      const spec=resourceSpec(form.dataset.kind,form.dataset.parent);const file=form.elements.attachment?.files?.[0];
      if(file&&file.size){if(file.size>10*1024*1024)throw new Error('Le fichier dépasse 10 Mo.');const response=await fetch('/api/uploads?name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':file.type},body:file});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Le fichier n’a pas été envoyé.');input[spec.fileKey]=payload.file.id}
      delete input.attachment;await api(spec.path,{method:'POST',body:JSON.stringify(input)});closeModal();await refresh();toast('Votre publication a été enregistrée.');return;
    }
    if(form.id==='complaint-reply'){await api('/complaints/'+encodeURIComponent(form.dataset.id)+'/messages',{method:'POST',body:JSON.stringify(input)});await openComplaint(form.dataset.id);return}
    if(form.id==='complaint-status'){await api('/complaints/'+encodeURIComponent(form.dataset.id),{method:'PATCH',body:JSON.stringify(input)});await refresh();await openComplaint(form.dataset.id);return}
    if(form.id==='space-message'){await api('/collaboration/'+encodeURIComponent(form.dataset.id)+'/discussions',{method:'POST',body:JSON.stringify(input)});await openSpace(form.dataset.id);return}
    if(form.id==='chat-form'){
      state.chatBusy=true;render();try{const result=await api('/assistant',{method:'POST',body:JSON.stringify({question:input.question,conversation_id:state.conversationId})});state.conversationId=result.conversation_id;state.chat.push({sender:'user',content:input.question},result.message)}finally{state.chatBusy=false;render()}return;
    }
    if(form.id==='campus-search'){state.contentQuery=input.query;state.query=input.query;render()}
  }catch(error){if(form.id==='experience-auth'&&form.dataset.mode==='reset-password'&&error.status===401){state.recoveryStatus='invalid';render()}else if(errorNode&&document.contains(errorNode))errorNode.innerHTML=notice(error.message,'error');else toast(error.message)}finally{if(submit)submit.disabled=false}
},true);
let contentSearchTimer;
document.addEventListener('input',event=>{if(event.target.id!=='content-search')return;const value=event.target.value,position=event.target.selectionStart;clearTimeout(contentSearchTimer);contentSearchTimer=setTimeout(()=>{state.contentQuery=value;render();const input=document.getElementById('content-search');input?.focus();input?.setSelectionRange(position,position)},200)});
window.addEventListener('hashchange',()=>{if(state.page!=='reset-password'){state.recoveryStatus='unknown';recoveryCheckSequence++}state.contentQuery='';if(state.page==='assistant'&&state.user)loadChats();if(location.hash==='#services-campus')document.getElementById('services-campus')?.scrollIntoView?.({behavior:'smooth'})});
const originalModal=modal,originalCloseModal=closeModal;
modal=function(content,wide=false){stopParticipantWatch();originalModal(content,wide)};
closeModal=function(){stopParticipantWatch();originalCloseModal()};
participants=liveParticipants;
render();
loadPublicSite();

document.addEventListener('change',event=>{
  const data=state.workspace.teaching;if(!data)return;
  if(event.target.id==='staff-program'){state.staffProgram=data.programs.some(p=>p.id===event.target.value)?event.target.value:'all';render()}
  if(event.target.id==='staff-semester'){state.staffSemester=data.semesters.some(s=>s.id===event.target.value)?event.target.value:'all';render()}
});
